/**
 * Dye Preview plugin (Wave 7.9).
 *
 * Hooks the `hb:inventory-drag-over` custom event (dispatched from
 * inventory.js paperdoll + items grid). When the player drags a
 * Dye Pot over a Dyeable armor, this plugin shows a tooltip
 * preview showing what the dyed armor would look like — composed
 * via the W7.8 wasm dye-preview compositor with byte-parity to the
 * server-side render path.
 *
 * The plugin is preview-ONLY. Committing the dye is a server-side
 * recipe (Dye Pot + Dyeable → cooking skill check); the player
 * still needs to release the drag (or use the dye-pot via the
 * normal `use on item` flow) to commit. This plugin's job is the
 * lowered-regret-cost UX: see the actual outcome at no risk before
 * spending the expensive dye pot.
 *
 * Wiki-grounded design (fandom Dyeing + Hennacin Dye Pot pages +
 * WorldObject_Networking.cs::CalculateObjDesc + RecipeManager_New.cs):
 *   - Dye color is determined by the DYE POT'S OWN PaletteTemplate +
 *     Shade properties; ACE recipes 3844 (base) and 9068 (rare
 *     eternal) just CopyFromSourceToTarget those values onto the
 *     armor on a successful skill check (see RecipeManager.cs:1272-
 *     1327 ModifyInt + the success-branch recipe_mods_int row
 *     `(index=1, stat=PaletteTemplate=3, enum=CopyFromSourceToTarget=3)`).
 *   - The (paletteTemplate, shade) catalog is data-driven (Wave 11
 *     follow-on): loaded lazily from `data/dye-recipes.json` which
 *     is regenerated by `scripts/build_dye_recipes.py` parsing the
 *     ACE-World-Database SQL dump. All 19 canonical dye-pot wcids
 *     are covered (9 base 8043-11477 + 10 rare eternal 30082-30091).
 *
 * Plugin lifecycle: registered in the bar via
 * `barSlots.push({...activate})` like other plugins. Its activate
 * does NOT mount any visible UI by default — the tooltip is created
 * on-demand at drag-over time + removed on drag-end. The bar slot
 * (an eyedropper / palette icon) is a discoverability hint + click
 * toggles whether previews fire (default: on).
 */

import { composeDyePreview, resolveDyeTriples } from "../ui/ac_dye_preview.js";
import { DyeViewport } from "../ui/ac_dye_viewport.js";
import { takeInventorySnapshot } from "./inventory_helpers.js";

const TOOLTIP_ID = "hb-dye-preview-tooltip";
const PLUGIN_STATE_KEY = "__hbDyePreviewState";

/**
 * Dye-pot → (paletteTemplate, shade) outcomes table, lazy-loaded from
 * `data/dye-recipes.json` on first access (regenerated by
 * `scripts/build_dye_recipes.py` from ACE's world database SQL dump).
 *
 * The catalog covers all 19 canonical dye-pot wcids (9 base-game pots
 * 8043-11477 + 10 rare eternal pots 30082-30091) extracted directly
 * from each dye-pot weenie's own PropertyInt.PaletteTemplate +
 * PropertyFloat.Shade. ACE's recipes 3844 (base) and 9068 (rare
 * eternal) just `CopyFromSourceToTarget` those values onto the dyed
 * armor at success time (see RecipeManager.cs:ModifyInt). So a single
 * (paletteTemplate, shade) lookup keyed by dye-pot wcid is sufficient
 * to recreate the retail color outcome.
 *
 * Lazy-load pattern mirrors the spellbook plugin's `loadCatalog()` at
 * plugins/spellbook.js:111-123 — single in-flight Promise cached in
 * module scope, force-cache so repeat fetches are free. `mount()`
 * kicks off the load eagerly so the cache is warm by the time the
 * first drag-over event fires. `isDyePot()` reads synchronously from
 * the cache (returns null until the load resolves; the warmup in
 * mount + the user's natural lag between page-load and first hover
 * make this effectively a no-op).
 */
let _dyePotsCache = null;            // wcid (number) -> outcome record
let _dyePotsPromise = null;           // single in-flight fetch promise

function loadDyePots() {
  if (!_dyePotsPromise) {
    _dyePotsPromise = fetch("./data/dye-recipes.json", { cache: "force-cache" })
      .then((r) => r.json())
      .then((j) => {
        // Coerce wcid keys to numbers so isDyePot's >>>0 lookup hits.
        const out = {};
        const src = j?.dyePots ?? {};
        for (const k of Object.keys(src)) out[+k] = src[k];
        _dyePotsCache = out;
        return out;
      })
      .catch((e) => {
        console.warn("[dye-preview] dye-recipes.json load failed:", e);
        _dyePotsCache = {};
        return {};
      });
  }
  return _dyePotsPromise;
}

/**
 * Return the dye-pot outcome record for a wcid, or null if not a
 * known dye pot (or if the catalog hasn't finished loading yet).
 *
 * Sync by design — the catalog is small (3KB) and is preloaded at
 * plugin-mount time, so by the time the first drag-over event fires
 * the cache is populated. If a caller hits this BEFORE the load
 * resolves, it returns null (preview tooltip silently skips this
 * frame; the user's next hover will succeed).
 */
export function isDyePot(wcid) {
  if (!_dyePotsCache) return null;
  return _dyePotsCache[wcid >>> 0] ?? null;
}

/**
 * Heuristic for "is this item a dyeable armor?". Per
 * `RecipeManager_New.cs:55` the server-side check is
 * `WeenieType == Clothing && PropertyBool.Dyable == true`. JS-side
 * we approximate via:
 *  - item.itemType has the armor/clothing bits (0x2 or 0x4 depending
 *    on the AC ItemType enum), OR
 *  - item.equipMask is non-zero (only equipable clothing has slots)
 *
 * The W7.9 wire protocol may not expose PropertyBool.Dyable yet,
 * so we err on the side of showing the preview when armor-shaped;
 * a non-dyeable armor's preview just produces null (no harm).
 */
export function isDyeable(item) {
  if (!item) return false;
  const equipMask = (item.equipMask >>> 0) || 0;
  if (equipMask !== 0) return true;
  const itemType = (item.itemType >>> 0) || 0;
  return (itemType & 0x6) !== 0;
}

function createTooltip() {
  let el = document.getElementById(TOOLTIP_ID);
  if (el) return el;
  el = document.createElement("div");
  el.id = TOOLTIP_ID;
  el.style.cssText = [
    "position: fixed",
    "z-index: 250",
    "max-width: 260px",
    "padding: 8px 10px",
    "background: rgba(28, 22, 14, 0.97)",
    "border: 1px solid #6e5a2c",
    "border-radius: 4px",
    "box-shadow: 0 6px 20px rgba(0, 0, 0, 0.65)",
    "color: #f0d8a0",
    "font-family: sans-serif",
    "font-size: 12px",
    "pointer-events: none",
    "user-select: none",
    "display: none",
  ].join(";");
  document.body.appendChild(el);
  return el;
}

function positionTooltip(el, clientX, clientY) {
  const w = el.offsetWidth || 260;
  const h = el.offsetHeight || 200;
  let left = clientX + 12;
  let top = clientY + 12;
  if (left + w > window.innerWidth) left = window.innerWidth - w - 8;
  if (top + h > window.innerHeight) top = clientY - h - 12;
  if (top < 8) top = 8;
  if (left < 8) left = 8;
  el.style.left = `${left}px`;
  el.style.top = `${top}px`;
}

function hideTooltip() {
  const el = document.getElementById(TOOLTIP_ID);
  if (el) el.style.display = "none";
  // Dispose any owned WebGL viewport so contexts don't accumulate
  // (Chrome caps ~16; even at one preview per hover we'd exhaust).
  const vp = window[VIEWPORT_REF_KEY];
  if (vp) {
    try { vp.dispose(); } catch (_) {}
    window[VIEWPORT_REF_KEY] = null;
  }
  // Wave 7.9.B — D.4: revert any active whole-mesh preview on the
  // local player rig. We stashed the original meta when the
  // preview was applied; calling applyAppearance with those values
  // restores the pre-preview state. Local-only — server isn't
  // aware so the next ObjectCreate would revert anyway.
  revertWholeMeshPreview();
}

const VIEWPORT_REF_KEY = "__hbDyePreviewViewport";
const WHOLE_MESH_STASH_KEY = "__hbDyePreviewWholeMeshStash";

function revertWholeMeshPreview() {
  const stash = window[WHOLE_MESH_STASH_KEY];
  if (!stash) return;
  window[WHOLE_MESH_STASH_KEY] = null;
  try {
    const em = window.liveScene3d?.entityManager;
    if (em?.applyAppearance && stash.guid) {
      em.applyAppearance(stash.guid, {
        modelChanges: stash.modelChanges ?? new Uint32Array(0),
        textureChanges: stash.textureChanges ?? new Uint32Array(0),
        subPalettes: stash.subPalettes ?? new Uint32Array(0),
        paletteId: stash.paletteId ?? 0,
      });
      try {
        window.__diag?.clothing?.onDyePreviewWholeMeshReverted?.({ guid: stash.guid });
      } catch (_) {}
    }
  } catch (_) {}
}

async function applyWholeMeshPreview(triples) {
  try {
    const lpg = (typeof window.getLocalPlayerGuid === "function") ? (window.getLocalPlayerGuid() >>> 0) : 0;
    if (!lpg) return false;
    const em = window.liveScene3d?.entityManager;
    if (!em?.applyAppearance) return false;
    const inst = em.entityMap?.get?.(lpg);
    const meta = inst?.meta;
    if (!meta) return false;
    // Stash the current substitutions so we can revert on hide.
    // Stash once per drag session — if already stashed, leave the
    // original values alone so subsequent Shift-drag-over events
    // don't accidentally overwrite the true original with an
    // already-previewed state.
    if (!window[WHOLE_MESH_STASH_KEY]) {
      window[WHOLE_MESH_STASH_KEY] = {
        guid: lpg,
        modelChanges: meta.modelChanges ?? new Uint32Array(0),
        textureChanges: meta.textureChanges ?? new Uint32Array(0),
        subPalettes: meta.subPalettes ?? new Uint32Array(0),
        paletteId: meta.paletteId ?? 0,
      };
    }
    await em.applyAppearance(lpg, {
      modelChanges: new Uint32Array(0),
      textureChanges: new Uint32Array(0),
      subPalettes: triples ?? new Uint32Array(0),
      paletteId: 0,
    });
    try {
      window.__diag?.clothing?.onDyePreviewWholeMeshApplied?.({
        guid: lpg, tripleCount: ((triples?.length ?? 0) / 3) | 0,
      });
    } catch (_) {}
    return true;
  } catch (_) {
    return false;
  }
}

async function showTooltipFor(state, draggedItem, hoveredItem, x, y) {
  const outcome = isDyePot(draggedItem?.wcid >>> 0);
  if (!outcome) return false;
  if (!isDyeable(hoveredItem)) return false;
  // Need (clothingId, setupDid) for the target armor. The wire item
  // record exposes `clothingBaseId` / `setupId` when ACE shipped
  // them — fall back to `modelId` which doubles as setupId for
  // most clothing items.
  const clothingId = (hoveredItem.clothingBaseId
    ?? hoveredItem.clothingTableId
    ?? hoveredItem.clothing_base
    ?? 0) >>> 0;
  const setupDid = (hoveredItem.setupId ?? hoveredItem.modelId ?? 0) >>> 0;
  if (clothingId === 0 || setupDid === 0) {
    // Show a "missing data" tooltip rather than nothing — the player
    // sees feedback that the plugin is alive but can't render this
    // specific item. Helpful diagnostic for the W7.9 wire-gap.
    const el = createTooltip();
    el.innerHTML = "";
    const title = document.createElement("div");
    title.style.fontWeight = "bold";
    title.style.marginBottom = "4px";
    title.textContent = `${outcome.name}`;
    el.appendChild(title);
    const note = document.createElement("div");
    note.style.opacity = "0.7";
    note.style.fontSize = "11px";
    note.textContent = "Preview unavailable — armor metadata not in wire packet yet.";
    el.appendChild(note);
    el.style.display = "block";
    positionTooltip(el, x, y);
    try { window.__diag?.clothing?.onDyePreviewShown?.({ source: "drag-over", reason: "missing-armor-metadata", dyePotWcid: draggedItem.wcid }); } catch (_) {}
    return true;
  }
  // Wave 7.9.A — replace the flat canvas with a small THREE.js
  // viewport so the player sees the armor in 3D, rotating on a
  // pedestal. Compute the dye triples once + pass to viewport
  // (which uses animationCache for parts + fetchEntitySurfacesPixels
  // for materials — same wasm path as the spawn-time render).
  const triples = await resolveDyeTriples(clothingId, outcome.paletteTemplate, outcome.shade);
  const el = createTooltip();
  el.innerHTML = "";
  const title = document.createElement("div");
  title.style.fontWeight = "bold";
  title.style.marginBottom = "6px";
  title.textContent = `${outcome.name} → ${hoveredItem.name ?? "Armor"}`;
  el.appendChild(title);

  const viewportWrap = document.createElement("div");
  // Wave 7.9.B — D.3 widens the viewport to 360px to fit the player
  // mesh next to the pedestal.
  viewportWrap.style.cssText = [
    "display: block",
    "width: 360px",
    "height: 280px",
    "border: 1px solid #6e5a2c",
    "background: linear-gradient(180deg, #2a2418, #1c160e 60%, #14110a)",
    "border-radius: 4px",
    "overflow: hidden",
  ].join(";");
  el.appendChild(viewportWrap);

  let composed = false;
  let viewport = null;
  let playerMeshLoaded = false;
  try {
    viewport = new DyeViewport(viewportWrap, 360, 280);
    composed = await viewport.loadDyedItem(
      setupDid,
      (hoveredItem.mtableId ?? 0) >>> 0,
      0,
      triples ?? new Uint32Array(0),
    );
    // D.3 — try to load the local player rig at half-scale next to
    // the pedestal as a reference frame. Best-effort: silently skips
    // if local player guid is unknown or no entity instance exists.
    try {
      const lpg = (typeof window.getLocalPlayerGuid === "function") ? (window.getLocalPlayerGuid() >>> 0) : 0;
      if (lpg !== 0) {
        const em = window.liveScene3d?.entityManager;
        const playerInst = em?.entityMap?.get?.(lpg);
        const playerMeta = playerInst?.meta;
        if (playerMeta) {
          const playerSetup = (playerMeta.modelId ?? playerMeta.setupId ?? 0) >>> 0;
          if (playerSetup !== 0) {
            playerMeshLoaded = await viewport.loadPlayerMesh(
              playerSetup,
              (playerMeta.mtableId ?? 0) >>> 0,
              (playerMeta.paletteId ?? 0) >>> 0,
              playerMeta.subPalettes ?? new Uint32Array(0),
            );
          }
        }
      }
    } catch (_) { /* D.3 best-effort */ }
    if (!composed) {
      // Viewport built but rig couldn't load — fall through to the
      // flat composeDyePreview as a backup so the player still sees
      // something.
      try { viewport.dispose(); } catch (_) {}
      viewport = null;
      viewportWrap.innerHTML = "";
      const fallbackCanvas = await composeDyePreview(clothingId, setupDid, outcome.paletteTemplate, outcome.shade);
      if (fallbackCanvas) {
        const maxH = 240;
        const scale = Math.min(1, maxH / Math.max(1, fallbackCanvas.height));
        fallbackCanvas.style.width = `${Math.round(fallbackCanvas.width * scale)}px`;
        fallbackCanvas.style.height = `${Math.round(fallbackCanvas.height * scale)}px`;
        fallbackCanvas.style.imageRendering = "pixelated";
        viewportWrap.appendChild(fallbackCanvas);
        composed = true;
      } else {
        viewportWrap.innerHTML = '<div style="padding:8px;opacity:0.7;">(no preview available)</div>';
      }
    } else {
      viewport.start();
      window[VIEWPORT_REF_KEY] = viewport;
    }
  } catch (e) {
    if (viewport) try { viewport.dispose(); } catch (_) {}
    viewport = null;
    viewportWrap.innerHTML = `<div style="padding:8px;opacity:0.7;">(viewport error: ${String(e?.message ?? e).slice(0, 60)})</div>`;
  }

  const note = document.createElement("div");
  note.style.opacity = "0.7";
  note.style.fontSize = "11px";
  note.style.marginTop = "6px";
  note.textContent = "⚠ Cooking skill check applies on drop.";
  el.appendChild(note);
  el.style.display = "block";
  positionTooltip(el, x, y);
  state.lastShownAt = performance.now();
  try {
    window.__diag?.clothing?.onDyePreviewShown?.({
      source: "drag-over",
      dyePotWcid: draggedItem.wcid,
      clothingId,
      setupDid,
      paletteTemplate: outcome.paletteTemplate,
      shade: outcome.shade,
      composed,
      mode: viewport ? "viewport-3d" : "flat-fallback",
      playerMeshLoaded,
    });
  } catch (_) {}
  return true;
}

// Fields showTooltipFor + the Shift whole-mesh path read off an inventory
// row. Copied out as plain numbers so the wasm boxes can be freed at the end
// of the lookup instead of being retained (and, before this, never freed at
// all) — see inventory_helpers.takeInventorySnapshot for why that matters.
function copyItemRow(it, guid) {
  return {
    guid,
    wcid: (it.wcid >>> 0) || 0,
    name: it.name || "",
    itemType: (it.itemType >>> 0) || 0,
    equipMask: (it.equipMask >>> 0) || 0,
    clothingBaseId: (it.clothingBaseId >>> 0) || 0,
    setupId: (it.setupId >>> 0) || 0,
    modelId: (it.modelId >>> 0) || 0,
  };
}

/**
 * Resolve BOTH drag guids from ONE `playerInventory()` snapshot, and release
 * it. This used to be two separate `playerInventory()` calls per drag-over
 * event, neither freed — see the debounce note in `mount()` for why that ran
 * on every single dragover rather than once per `debounceMs`.
 *
 * @returns {{dragged: object|null, hovered: object|null}}
 */
function getInventoryItems(draggedGuid, hoveredGuid) {
  const out = { dragged: null, hovered: null };
  if (!draggedGuid && !hoveredGuid) return out;
  const handle = window.__sessionHandle ?? window.__pluginClient?._handle;
  const snap = takeInventorySnapshot(handle);
  try {
    for (const it of snap.inv) {
      if (draggedGuid && !out.dragged && String(it.guid) === String(draggedGuid)) {
        out.dragged = copyItemRow(it, draggedGuid);
      }
      if (hoveredGuid && !out.hovered && String(it.guid) === String(hoveredGuid)) {
        out.hovered = copyItemRow(it, hoveredGuid);
      }
      if ((!draggedGuid || out.dragged) && (!hoveredGuid || out.hovered)) break;
    }
  } finally {
    snap.free();
  }
  return out;
}

/**
 * Plugin manifest + mount. Matches vendor-ui.js / combat-bar.js
 * pattern. `iconHidden: true` because the plugin is reactive — no
 * bar slot of its own; subscribes to inventory drag events and
 * renders an ephemeral tooltip when appropriate.
 */
export const manifest = {
  id: "dye-preview",
  name: "Dye Preview",
  icon: "🎨",
  iconHidden: true,
  version: "0.1.0",
  description: "Preview tooltip when a Dye Pot is dragged over a dyeable armor — wiki-grounded outcome via wasm compositor.",
};

export function mount(/* ctx */) {
  const state = (window[PLUGIN_STATE_KEY] = window[PLUGIN_STATE_KEY] ?? {
    enabled: true,
    lastShownAt: 0,
    // The debounce gate's OWN clock. It used to be `lastShownAt`, which is
    // only stamped when a tooltip actually renders (showTooltipFor's tail) —
    // so on the overwhelmingly common path (dragging anything that is not a
    // dye pot over anything that is not dyeable) the gate never engaged and
    // every single HTML5 `dragover` (continuous while the pointer moves; see
    // inventory.js:2806 "the event fires continuously during drag;
    // subscribers debounce as needed") ran two full `playerInventory()`
    // snapshots. Stamping evaluation time is what actually throttles.
    lastEvalAt: 0,
    debounceMs: 60,
    handlerDragOver: null,
    handlerDragEnd: null,
  });
  // A state object persisted from a previous mount predates `lastEvalAt`.
  if (!Number.isFinite(state.lastEvalAt)) state.lastEvalAt = 0;

  // Wave 11 — eagerly preload the dye-recipes catalog so the cache is
  // warm by the time the first drag-over event fires. Fire-and-forget;
  // isDyePot() returns null until the load resolves (initial frames
  // silently skip the preview, which is fine since the player needs
  // a moment to drag a dye pot anyway).
  loadDyePots();

  // Single registration regardless of how many times mount is called.
  if (state.handlerDragOver) {
    window.removeEventListener("hb:inventory-drag-over", state.handlerDragOver);
  }
  state.handlerDragOver = async (ev) => {
    if (!state.enabled) return;
    const now = performance.now();
    if (now - state.lastEvalAt < state.debounceMs) return;
    state.lastEvalAt = now;
    const detail = ev.detail ?? {};
    const { dragged: draggedItem, hovered: hoveredItem } =
      getInventoryItems(detail.draggedGuid, detail.hoveredGuid);
    if (!draggedItem || !hoveredItem) {
      hideTooltip();
      return;
    }
    const shown = await showTooltipFor(state, draggedItem, hoveredItem, detail.clientX, detail.clientY);
    if (!shown) {
      hideTooltip();
      return;
    }
    // Wave 7.9.B — D.4: when Shift held, ALSO apply the dye to the
    // local player's actual rig in the main scene for a whole-mesh
    // preview. Local-only — reverts on hide / drag-end.
    if (detail.shiftKey) {
      const outcome = isDyePot(draggedItem.wcid >>> 0);
      const clothingId = (hoveredItem.clothingBaseId ?? 0) >>> 0;
      if (outcome && clothingId !== 0) {
        const triples = await resolveDyeTriples(clothingId, outcome.paletteTemplate, outcome.shade);
        if (triples) await applyWholeMeshPreview(triples);
      }
    }
  };
  window.addEventListener("hb:inventory-drag-over", state.handlerDragOver);
  if (state.handlerDragEnd) {
    window.removeEventListener("hb:inventory-drag-end", state.handlerDragEnd);
  }
  state.handlerDragEnd = () => hideTooltip();
  window.addEventListener("hb:inventory-drag-end", state.handlerDragEnd);

  return () => {
    if (state.handlerDragOver) window.removeEventListener("hb:inventory-drag-over", state.handlerDragOver);
    if (state.handlerDragEnd) window.removeEventListener("hb:inventory-drag-end", state.handlerDragEnd);
    state.handlerDragOver = null;
    state.handlerDragEnd = null;
    hideTooltip();
  };
}

/**
 * Test helper — call from harness to verify the preview path without
 * actually dragging. Exported for the wire-agent verification harness
 * to bypass the synthetic-drag-event ceremony.
 */
export async function _testShowPreview(draggedItem, hoveredItem, x, y) {
  const state = (window[PLUGIN_STATE_KEY] = window[PLUGIN_STATE_KEY] ?? { enabled: true, lastShownAt: 0, lastEvalAt: 0 });
  state.lastShownAt = 0; // bypass debounce
  state.lastEvalAt = 0;
  return showTooltipFor(state, draggedItem, hoveredItem, x, y);
}

/** Hide the tooltip — exported for test cleanup. */
export function _testHideTooltip() {
  hideTooltip();
}

/** Diag accessor for `__diag.clothing` cached read-through. */
export function getDyePreviewPluginSnapshot() {
  const state = window[PLUGIN_STATE_KEY] ?? null;
  // _dyePotsCache populates after the first load resolves (which
  // mount() kicks off eagerly). Before then, knownDyePots is [].
  const knownDyePots = _dyePotsCache
    ? Object.keys(_dyePotsCache).map((k) => +k)
    : [];
  return {
    enabled: state?.enabled ?? false,
    lastShownAt: state?.lastShownAt ?? 0,
    lastEvalAt: state?.lastEvalAt ?? 0,
    debounceMs: state?.debounceMs ?? 0,
    knownDyePots,
    catalogLoaded: _dyePotsCache !== null,
  };
}

/**
 * Test/wire-harness helper — explicitly await the catalog load. Useful
 * for the wire-agent verification harness so it can guarantee the
 * cache is warm before triggering a synthetic drag-over event.
 */
export function _testLoadDyePots() {
  return loadDyePots();
}
